func TestCountOrdersByCountThenValue(t *testing.T) {
	got := Count([]string{"b", "a", "b", "c", "a", "b", "z", "c", "B", "B"})
	want := []Entry{{"b", 3}, {"B", 2}, {"a", 2}, {"c", 2}, {"z", 1}}
